var maxNiceDivisors = function(primeFactors) {
    if (primeFactors <= 3) return primeFactors;
    const MOD = 1000000007n;

    function modPow(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    const q = Math.floor(primeFactors / 3);
    const r = primeFactors % 3;
    if (r === 0) return Number(modPow(3n, q));
    if (r === 1) return Number((4n * modPow(3n, q - 1)) % MOD);
    return Number((2n * modPow(3n, q)) % MOD);
};
